mapper.select:
SELECT TL.*, TLP.pictureUrl AS extra__pictureUrl, TLT.typeName AS extra__locationType FROM tripLocation AS TL LEFT JOIN tripLocationPicture AS TLP ON TL.id = TLP.tripLocationId INNER JOIN tripLocationType AS TLT ON TL.locationTypeId = TLT.id WHERE TL.areaCode = #{areaCode}
AND TLT.typeName = #{locationType}
GROUP BY TL.id ORDER BY reviewCount DESC
